/* المرحلة ٢: النبتة الصغيرة (٥–٧ سنوات) — المدرسة الإنجليزية · سيناريوهات كاملة */
window.SD.stages.push({id:2,icon:'🎒',color:'#2E86DE',name:'النبتةُ الصغيرة',years:'٥–٧ سنوات',place:'المدرسة الإنجليزية — مانشستر',
intro:'أول خروج من حضن البيت إلى العالم: مدرسة إنجليزية، أسئلة الأصدقاء، الغداء الحلال، الصلاة الأولى في السابعة. هنا تُختبر البذور التي زرعتها المرحلة الأولى — ويتعلم البطل أن يكون مسلماً واثقاً بين من يخالفونه.',
eps:[
{n:15,t:'أولُ يومٍ في المدرسة',ic:'🏫',age:'٥ سنوات',loc:'مدرسة الحي — مانشستر',corner:'academy',goal:'دعاء طلب العلم والشجاعة عند البدايات الجديدة — «ربِّ زدني علماً» زاد المدرسة',chars:['صلاح الدين','أيوب','مريم','عمر','المعلمة السيدة كلارك'],
scenes:[
{h:'م١ · داخلي — غرفة صلاح الدين، ليلة قلقة',d:'حقيبة مدرسية جديدة معلقة على الباب كأنها وحش صغير. الطفل يتقلب في سريره ولا ينام. يدخل أيوب ويجلس على طرف السرير.',dlg:[['صلاح الدين','بابا… لا أعرفُ أحداً هناك. ماذا لو ضعتُ؟ ماذا لو ضحكوا مني؟'],['أيوب','أتعرفُ سراً عن الشجعان يا صلاح الدين؟ الشجاعُ ليس الذي لا يخاف… الشجاعُ الذي يخافُ ثم يمشي! ونبيُّنا ﷺ ما طلبَ من اللهِ زيادةً في شيءٍ إلا في العلم: قل ربِّ زدني علماً. أنتَ غداً ذاهبٌ لتكسبَ كنزاً.'],['صلاح الدين','(يفكر) إذن أنا… تاجرُ كنوز؟'],['أيوب','(يضحك ويطفئ النور) أذكى تاجرٍ في مانشستر.']],vo:'خمسُ سنوات، وأولُ معركةٍ لي خارجَ أسوارِ البيت. لم يكن معي سيفٌ ولا درع… كان معي شيءٌ أقوى.'},
{h:'م٢ · خارجي — بوابة المدرسة، صباح',d:'ضجيج أطفال وأمهات. مريم تجثو أمام ابنها، تفتح كفه الصغيرة وترسم فيها بإصبعها وهي تهمس، ثم تغلق أصابعه عليها كمن يخبئ جوهرة.',dlg:[['مريم','بسمِ اللهِ توكلتُ على الله… خبأتُها في كفِّك. كلما خفتَ، اضغطْ عليها هكذا. ومعها بطاقةٌ في جيبِك، كتبتُ لك الدعاء.'],['صلاح الدين','(يضغط كفه بقوة ويتنفس) بسمِ الله… حسناً. أنا ذاهب. (يمشي ثلاث خطوات ثم يعود يحضنها بسرعة ويهرب نحو الباب)']]},
{h:'م٣ · داخلي — الصف، حصة الصباح',d:'صف ملون بثلاثين طفلاً. المعلمة كلارك تسأل بالإنجليزية: من يعرف عدد أرجل العنكبوت؟ صلاح الدين يعرف الجواب من لعبة «من صنعها؟» — لكن الكلمات الإنجليزية تتزاحم في فمه. يده ترتفع نصف رفعة ثم تهبط. لقطة قريبة: كفه المغلقة على البسملة… يضغطها، ويرفع يده عالياً.',dlg:[['صلاح الدين','(بإنجليزية متأنية) ثمان! العنكبوتُ له ثمانُ أرجل… وهو يبني بيتَهُ بخيوطٍ أقوى من الحديد… لو كانت بحجمِ الحبل!'],['المعلمة كلارك','(مندهشة) هذا صحيحٌ تماماً! ومن أين تعرفُ هذا يا صلاح الدين؟'],['صلاح الدين','من أبي… نلعبُ لعبةَ: من صنعَها؟']]},
{h:'م٤ · داخلي — ساحة الغداء',d:'يجلس وحيداً بصندوق غدائه. طفل أسمر بابتسامة واسعة يقترب حاملاً صندوقاً يشبه صندوقه، يفتح غطاءه: سمبوسة!',dlg:[['عمر','رأيتُكَ تقولُ بسم الله قبل الأكل! أنتَ مسلم؟ أنا عمر! أمي من باكستان — نحن أيضاً نقولُها!'],['صلاح الدين','(يضيء وجهه) وأنا صلاحُ الدين!… عندك سمبوسة وعندي كعكُ أمي. نتقاسم؟'],['عمر','(يمد يده) أفضلُ صفقةٍ في المدرسة!']],vo:'هكذا، في أولِ يومٍ، اكتشفتُ قانونَ الغربةِ الجميل: قل بسمِ اللهِ بصوتٍ مسموع… يجدْكَ إخوانُك.'},
{h:'م٥ · داخلي — البيت، مساءً',d:'يقتحم البيت راكضاً، الحقيبة تتطاير خلفه. يعلق فوق مكتبه الصغير ورقة كتبها بخط متعثر: «ربِّ زدني علماً».',dlg:[['صلاح الدين','(لاهثاً) ماما! المدرسةُ فيها كنوز! تعلمتُ حرفاً إنجليزياً جديداً، وأجبتُ عن العنكبوت، وكسبتُ صديقاً اسمُهُ عمر يقولُ بسمِ الله مثلنا!'],['مريم','(تنظر لأيوب) قلتَ له تاجرُ كنوز؟… عاد التاجرُ رابحاً من أولِ يوم.']]}],
msg:'الشجاعُ يخافُ ثم يمشي: خذ معك «بسم الله توكلت على الله» و«ربِّ زدني علماً» — تفتح لك البداياتُ أبوابها.',apply:'قبل أي بداية جديدة (مدرسة، نادٍ، امتحان) قل: «بسم الله توكلت على الله» و«ربِّ زدني علماً» — وارفع يدك مرةً اليوم مهما ترددت.'},

{n:16,t:'صندوقُ الغداءِ الأخضر',ic:'🥪',age:'٥ سنوات',loc:'مقصف المدرسة',corner:'aqeeda',goal:'الحلال هوية لا حرج فيها — يرفض بأدب ويشرح بثقة',chars:['صلاح الدين','عمر','توم','طفل ساخر (بيلي)','مشرفة المقصف'],
scenes:[
{h:'م١ · داخلي — مقصف المدرسة، طابور الطعام',d:'صواني تتدافع. اليوم وجبة المدرسة مجانية للجميع: نقانق ساخنة رائحتها تملأ المكان. المشرفة تضع النقانق في صحن صلاح الدين قبل أن يتكلم.',dlg:[['صلاح الدين','(يرد الصحن بلطف وبأدب تعلمه) شكراً جزيلاً… لكن لا أستطيعُ أكلَ هذه. عندي طعامي.'],['المشرفة','إنها لذيذة يا صغير! لمَ لا؟'],['صلاح الدين','نحن نأكلُ الحلالَ فقط — هكذا وصّانا ربُّنا. ومعي صندوقي الأخضر!']],vo:'كان أسهلَ شيءٍ أن آخذَ الصحنَ وأصمت. لكنَّ أبي علَّمَني جملةً لا تُنسى: الذي يستحي من دينِهِ في الصغيرة… يضيِّعُهُ في الكبيرة.'},
{h:'م٢ · داخلي — طاولة الغداء',d:'يفتح صندوقه الأخضر: أرز أمه وكفتة وسمبوسة. طفل ضخم قليلاً (بيلي) يشير لصندوقه ويرفع صوته.',dlg:[['بيلي','انظروا! طعامُهُ غريب! ورفضَ النقانق! أكلُكم عجيبٌ يا هذا!'],['صلاح الدين','(يرفع رأسه بهدوء، بلا غضب) ليس عجيباً… هو طيب. نحن نأكلُ الطيبَ فقط: هذه وصيةُ ربنا. وهذه السمبوسة أطيبُ من كلِّ نقانقِ المدينة — جرِّبْ واحدةً إن أردت.'],['بيلي','(محتار — توقع بكاءً فوجد دعوة!) أنا… ليس اليوم.']]},
{h:'م٣ · داخلي — الطاولة نفسها',d:'توم يجلس بجانبه ويأخذ سمبوسة بفضول، يقضمها… تتسع عيناه.',dlg:[['توم','هذا ألذُّ شيءٍ أكلتُهُ في المقصف منذ ولدت! لماذا لا يبيعونها هنا؟!'],['عمر','(يضحك ويفتح صندوقه) وعندي أنا برياني! يا توم، اجلس بيننا كلَّ يوم — طاولتُنا أغنى طاولةٍ في مانشستر!'],['المعلمة كلارك','(تمر وتبتسم) يبدو أن هذه الطاولة تحتاج تصريحَ مطعم!']],vo:'وهكذا انقلبَ المشهد: الصندوقُ الذي كادَ يكونُ سببَ سخرية… صارَ أشهرَ صندوقٍ في المقصف.'},
{h:'م٤ · داخلي — الصف، حصة ما بعد الغداء',d:'المعلمة كلارك تستغل الموقف بذكاء تربوي: ترسم على السبورة أطباقاً من العالم.',dlg:[['المعلمة كلارك','اليوم تعلمنا شيئاً جميلاً: لكلِّ عائلةٍ طعامُها وقواعدُها. صلاح الدين، احكِ لنا: ماذا يعني الحلال؟'],['صلاح الدين','(يقف واثقاً) يعني الطيب! نحن لا نأكلُ إلا ما أذنَ به الله… نقولُ بسمِ الله، ونأكلُ باليمين، ولا نرمي الطعام. أمي تقول: الجسدُ الذي يكبرُ على الحلال… يحبُّ الخيرَ أكثر.']]},
{h:'م٥ · داخلي — البيت، مساءً',d:'يحكي القصة على العشاء. أيوب يضع يده على كتفه.',dlg:[['أيوب','أتدري ما أجملَ ما فعلتَ اليوم؟ ليس رفضَ النقانق… بل أنكَ رفضتَ بابتسامة. من تركَ شيئاً للهِ وهو مبتسم، عوَّضَهُ اللهُ خيراً منه.'],['صلاح الدين','عوَّضَني فعلاً! توم وعمر صارا يحجزانِ مكاني كلَّ يوم… ويطلبانِ من أمي سمبوسة زيادة!']],vo:'يا أصدقائي: الحلالُ ليس قيداً… الحلالُ تاج. من لبسَهُ صغيراً بثقة، مشى به كبيراً بعزّة.'}],
msg:'الحلالُ هويتُنا وتاجُنا: نرفضُ ما لا يحلُّ بأدبٍ وابتسامة — ومن ترك شيئاً لله عوضه الله خيراً منه.',apply:'إذا قُدّم لك ما لا يحل (أو ما لا يناسبك) فتدرّب على جملة الرفض المهذب: «لا شكراً — نحن نأكل الحلال الطيب» بابتسامة.'},

{n:17,t:'توم يسأل: من هو الله؟',ic:'💭',age:'٦ سنوات',loc:'حديقة البيتين',corner:'aqeeda',goal:'دعوة الفطرة بلغة الأطفال — الإجابة عن أسئلة غير المسلمين ببساطة وجمال',chars:['صلاح الدين','توم','أيوب'],
scenes:[
{h:'م١ · خارجي — حديقة آل ويلسون، عصر صيفي',d:'الطفلان على أرجوحة خشبية يتناوبان الدفع. توم يتوقف فجأة عن الدفع، وجهه جاد على غير عادته.',dlg:[['توم','صلاح الدين… سؤال. أنتم تصلّون كثيراً، وتقولون بسم الله قبل كلِّ شيء… من هو الله؟'],['صلاح الدين','(يتجمد على الأرجوحة — أكبر سؤال في العالم يسقط عليه فجأة)… الله؟ الله هو…']],vo:'ستُّ سنواتٍ من عمري، وسألني جاري السؤالَ الذي تحارُ فيه العقولُ الكبيرة. وفجأة… تذكرتُ الحديقة. حديقةَ أبي ولعبتَنا القديمة.'},
{h:'م٢ · خارجي — جولة في حديقة توم نفسها',d:'يقفز صلاح الدين من الأرجوحة ويجر توم من يده متحمساً: يريه زهرة عباد الشمس التي تدير وجهها مع الشمس، ونملة تحمل حبة أكبر منها، وسحابة تعبر.',dlg:[['صلاح الدين','تعال! سأريكَ الجواب! هذه الزهرةُ تلتفُّ مع الشمسِ طولَ النهار — من علَّمها؟ وهذه النملةُ تحملُ ضعفَ وزنِها وتعرفُ بيتَها بلا خريطة — من دلَّها؟ والمطرُ الذي يسقي حديقتَكم — من يرسلُه؟'],['توم','(يفكر بجدية) ماما تقول: الطبيعة…'],['صلاح الدين','والطبيعةُ نفسُها؟ ساعةُ أبيكَ الجميلة — هل صنعتْ نفسَها؟ لا بدَّ من صانع! الذي صنعَ كلَّ هذا هو الله: واحدٌ لا شريكَ له، خلقَنا ويرانا ويحبُّنا… وهو الذي أعطاكَ عينيكَ اللتين تنظرُ بهما الآن!']]},
{h:'م٣ · خارجي — تحت شجرة الحديقة',d:'يجلسان. توم يطرح السؤال الثاني الأصعب.',dlg:[['توم','لكن… لماذا لا نراه؟'],['صلاح الدين','(يهمس كمن يفشي سراً) هل رأيتَ الريحَ يوماً؟ لا! لكنكَ ترى الأشجارَ ترقصُ بها فتعرفُ أنها موجودة. نحن نرى صنعةَ اللهِ في كلِّ مكان… وأبي يقول: سنراهُ في الجنةِ إن كنا من الطيبين — وهذا أجملُ وعدٍ في الدنيا!'],['توم','(يتأمل السماء طويلاً) دينُكم… يجعلُ كلَّ شيءٍ له معنى. حتى النملة.']]},
{h:'م٤ · داخلي — بيت صلاح الدين، ليلاً',d:'صلاح الدين قلق، يستشير أباه وهو يقلب بطاقة في يده.',dlg:[['صلاح الدين','بابا… سألني توم عن الله. أجبتُهُ بلعبةِ من صنعها. هل أجبتُ صح؟ وهل سيصيرُ مسلماً الآن؟'],['أيوب','(يجلسه في حجره) أجبتَ أجملَ إجابة — بالفطرةِ التي تفهمُها القلوبُ الصغيرة. لكن اسمع يا بطل: نحن علينا البلاغُ الجميل… والهدايةُ بيدِ اللهِ وحدَه. لا تستعجل ثمرةَ توم — اسقِها بصدقِكَ وأخلاقِكَ سنةً بعد سنة، ودَعْ للهِ أمرَها.'],['صلاح الدين','مثل بذرةِ البلوط؟ تحتاجُ سنينَ لتصيرَ شجرة؟'],['أيوب','(يبتسم بعمق) بالضبط… مثلُ بذرةِ البلوط.']],vo:'لم أعرف يومَها أنَّ هذهِ البذرةَ ستكبرُ عشرين سنة… ثم تثمرُ في مسجدِ النورِ ثمرةً تُبكي الرجال. اصبروا على بذورِكم يا أصدقائي.'},
{h:'م٥ · خارجي — بين البيتين، الغد',d:'صلاح الدين يمد يده من فوق السور بهدية صغيرة: كتاب أطفال مصور عن أسماء الله الحسنى بالإنجليزية.',dlg:[['صلاح الدين','هذا لك! فيه أسماءُ اللهِ الجميلة… الرحمن: الذي يرحمُ الجميع، الرزاق: الذي يطعمُ كلَّ عصفور!'],['توم','(يقلب الصفحات ببطء) الرحمن… اسمٌ جميل. شكراً يا جاري.']]}],
msg:'أجمل جواب عن «من هو الله؟» هو جواب الفطرة: انظر حولك واسأل من صنعها — وعلينا البلاغ الجميل، والهداية بيد الله.',apply:'جهّز جواباً من جملتين لسؤال «من هو الله؟» وتدرّب عليه — فأنت سفير هذا الدين أمام من يسألك.'},

{n:18,t:'أقوى وأحب',ic:'🏊',age:'٦ سنوات',loc:'نادي السباحة — مانشستر',corner:'sport',goal:'«المؤمن القوي خير وأحب إلى الله» — الرياضة عبادة بناء لا مجرد لعب',chars:['صلاح الدين','أيوب','المدرب السيد هاريس','عمر'],
scenes:[
{h:'م١ · داخلي — مسبح النادي، الحصة الأولى',d:'مسبح أزرق ضخم يفوح بالكلور. أطفال ينزلقون كالأسماك. صلاح الدين على الحافة، طوق برتقالي حول خصره، يرتجف. يقفز… فيشرق بالماء ويخرج يسعل والدموع في عينيه، وضحكات خافتة من بعض الأطفال.',dlg:[['صلاح الدين','(للمدرب وهو يلهث) أريدُ الخروج! الماءُ دخلَ أنفي! الجميعُ أسرعُ مني!'],['المدرب هاريس','هذا أولُ درسٍ يا فتى: كلُّ سمكةٍ في هذا المسبحِ شرقتْ يوماً مثلك.']],vo:'أولُ حصةِ سباحةٍ في حياتي… خرجتُ منها وأنا أجرُّ الطوقَ البرتقاليَّ ورائي، وقررتُ قراراً حاسماً: لن أعودَ أبداً. أو هكذا ظننت.'},
{h:'م٢ · داخلي — السيارة، طريق العودة',d:'صلاح الدين ملفوف بالمنشفة، عابس، شعره يقطر. أيوب يقود بهدوء ولا يوبخ.',dlg:[['صلاح الدين','لن أرجعَ للنادي. السباحةُ ليست لي.'],['أيوب','حسناً… لكن قبل أن تقرر، أخبرني: من أحبُّ إلى الله — المؤمنُ القويُّ أم الضعيف؟'],['صلاح الدين','(يفكر)… القوي؟'],['أيوب','قالها رسولُ اللهِ ﷺ: المؤمنُ القويُّ خيرٌ وأحبُّ إلى اللهِ من المؤمنِ الضعيف. جسدُكَ هذا يا صلاح الدين أمانةٌ وجندي — ستحملُ به المصحف، وتساعدُ به الناس، وربما تنقذُ به غريقاً يوماً ما. التدريبُ ليس لعباً… التدريبُ عبادةُ الأقوياء.'],['صلاح الدين','(يخرج رأسه من المنشفة ببطء) عبادة؟… إذن سأرجع. لكن بشرط: لا طوق برتقالي!'],['أيوب','(يضحك) اتفقنا — تكسبُ خلعَهُ بالتدريب.']]},
{h:'م٣ · داخلي — المسبح، مونتاج أربعة أسابيع',d:'مونتاج إيقاعي: أسبوع أول — يتشبث بالحافة ويضرب الماء بقدمين غاضبتين. أسبوع ثانٍ — يطفو ثلاث ثوانٍ ويغرق ضاحكاً. أسبوع ثالث — أول ثلاثة أمتار متخبطة، والمدرب هاريس يهز رأسه معجباً. لوحة على جدار غرفته تُملأ: «حصصي — لا غياب». عمر ينضم للنادي ويشجعه من الحافة.',dlg:[['المدرب هاريس','(لأيوب على الحافة) ابنُكَ ليس الأسرعَ في المجموعة… لكنه الوحيدُ الذي لم يغبْ حصةً واحدة. وهذا النوعُ هو الذي يصلُ آخرَ الأمر.']],vo:'أربعةُ أسابيعَ من الماءِ في أنفي. لكنَّ جملةَ أبي كانت تسبحُ معي: عبادةُ الأقوياء… عبادةُ الأقوياء. وذاتَ خميس…'},
{h:'م٤ · داخلي — المسبح، لحظة العبور',d:'صمت مشوق. صلاح الدين عند الحافة بلا طوق لأول مرة. يأخذ نفساً عميقاً: «بسم الله» — وينطلق: ذراع، ذراع، نَفَس… المسافة تطول، يكاد يتوقف في المنتصف، يرى وجه أبيه عبر الزجاج… ويكمل. يده تلمس الحافة الأخرى. ينفجر الفريق تصفيقاً.',dlg:[['عمر','(يصرخ) قطعَ المسبحَ كاملاً! صلاحُ الدين قطعَهُ كاملاً!'],['صلاح الدين','(يلهث ويرفع ذراعه… ثم يهمس لنفسه) الحمدُ لله… هذه لكَ يا رب.']]},
{h:'م٥ · خارجي — أمام النادي، مساءً',d:'أيوب يعلق على صدر ابنه المبتل «ميدالية» صنعها من ورق ذهبي في البيت: كتب عليها «المؤمن القوي».',dlg:[['أيوب','لم تسبقِ الأطفالَ اليوم… سبقتَ نفسَكَ القديمة. وهذا أصعبُ سباقٍ في الدنيا.'],['صلاح الدين','(يمسك الميدالية الورقية بفخر كأنها ذهب حقيقي) العامَ القادم… أسبقُ نفسي الجديدةَ أيضاً!']],vo:'احتفظتُ بتلكَ الميداليةِ الورقيةِ عمري كلَّه — حتى وأنا أحملُ ذهبَ البطولاتِ الحقيقية. لأنها علمتني القاعدة: البطلُ من يسبقُ نفسَه.'}],
msg:'المؤمنُ القويُّ خيرٌ وأحبُّ إلى الله: جسدك أمانة فدرّبه — والبطل الحقيقي من يسبق نفسه القديمة.',apply:'اختر رياضة (سباحة أفضل) والتزم بها: حصتان أسبوعياً على الأقل — وانوِ بها القوة لطاعة الله.'},

{n:19,t:'النجومُ الذهبية',ic:'⭐',age:'٦ سنوات',loc:'صف المدرسة',corner:'social',goal:'الصدق حتى لو خسرت الجائزة — النجومية الحقيقية عند الله',chars:['صلاح الدين','المعلمة كلارك','زملاء الصف','مريم'],
scenes:[
{h:'م١ · داخلي — الصف، إعلان المسابقة',d:'لوحة كبيرة على الجدار: «تحدي القراءة» — اسم كل طفل وبجانبه نجوم ذهبية لامعة، وفي الأعلى صورة الجائزة: كأس صغيرة ورحلة لمكتبة المدينة الكبرى. المعلمة تشرح: كل كتاب تنهيه في البيت = نجمة.',vo:'كانت النجومُ الذهبيةُ تلمعُ على اللوحةِ كأنها نجومُ السماء. وكنتُ أريدُ الكأسَ… أريدُها بشدة. وهنا بدأتِ الحكاية.'},
{h:'م٢ · داخلي — الصف، بعد أسبوعين',d:'اللوحة تكشف السباق: بعض الأطفال جمعوا نجوماً كثيرة بسرعة عجيبة. في الاستراحة يتهامس طفلان قرب اللوحة وصلاح الدين يسمع.',dlg:[['طفل أول','(هامساً بفخر) أنا لم أقرأ إلا الصور! أقولُ لها أنهيتُهُ فتعطيني النجمة!'],['طفل ثانٍ','وأنا أخبرتُها بثلاثةِ كتبٍ في يومٍ واحد! هي لا تتأكد!'],['صلاح الدين','(ينظر إلى نجومه الأربع الصادقة… ثم إلى نجومهم السبع… ويبتلع شيئاً مراً)']],},
{h:'م٣ · داخلي — غرفة صلاح الدين، ليلاً',d:'كتاب خامس نصف مقروء على السرير. الوسوسة تتجسد صوتاً داخلياً والكاميرا قريبة من عينيه.',dlg:[['صوت الوسوسة','قل إنكَ أنهيتَه… بقيتْ صفحاتٌ قليلة، ما الفرق؟ كتابٌ واحد… من سيعرف؟'],['صلاح الدين','(يجلس فجأة ويرفع سبابته في العتمة — حركته القديمة) من سيعرف؟… اللهُ يعرف! (يتذكر — فلاش سريع: المزهرية المكسورة، صوت أمه: الولدُ الصادقُ لا يُشترى بكنوزِ الأرض) لا. سأقولُ أربعةً ونصفاً… لأنها أربعةٌ ونصف.']],vo:'تلكَ الليلةَ عرفتُ أنَّ أصعبَ الكذبِ ليس الكبير… بل الصغيرُ الذي «لا يضرُّ أحداً». وأنَّ النجمةَ المسروقةَ تحرقُ اللوحةَ كلَّها.'},
{h:'م٤ · داخلي — الصف، يوم الحسم',d:'المعلمة كلارك تحمل الكتب نفسها وتجلس أمام اللوحة: «قبل إعلان الفائز… لنلعب لعبة! سأسأل كل بطل عن كتبه». الأسئلة تبدأ: ماذا فعل الأرنب في نهاية القصة؟ من أكل الفطيرة؟ — أصحاب النجوم السريعة يتلعثمون ويحمرّون واحداً بعد الآخر. تصل لصلاح الدين فيحكي قصصه الأربع بتفاصيلها وأصواتها حتى يضحك الصف.',dlg:[['المعلمة كلارك','(تقف بهدوء وتنزع بعض النجوم من اللوحة) النجومُ المزيفةُ تسقطُ يا أحبائي… دائماً تسقط. أما أنت يا صلاح الدين — أربعُ نجومٍ حقيقية، وقصةٌ خامسةٌ قلتَ عنها الحقيقة. لهذا كأسُ هذا الشهرِ لك: ليس لأنكَ قرأتَ أكثر… بل لأنَّ كلَّ نجمةٍ لكَ من ذهبٍ حقيقي.']]},
{h:'م٥ · داخلي — البيت، مساءً',d:'الكأس الصغيرة على رف صلاح الدين بجانب ميدالية «المؤمن القوي» الورقية. مريم تضع بجانبها ورقة مطوية.',dlg:[['مريم','هديتي لفوزِك… ليست لعبة. (يفتح الورقة: مكتوب بخطها الجميل: عليكم بالصدقِ فإنَّ الصدقَ يهدي إلى البر) احفظْها… فهي التي أوصلتكَ للكأس.'],['صلاح الدين','(يقرأ بتأنٍ ثم يلصقها تحت الكأس مباشرة) حتى يعرفَ الكأسُ لماذا جاء!']],vo:'رفُّ غرفتي الصغيرُ كان يمتلئ… لا بالجوائز، بل بالقصصِ التي خلفَها. وقصةُ النجومِ علمتني: نجمةٌ صادقةٌ واحدة… تزنُ سماءً من المزيف.'}],
msg:'النجومُ المزيفةُ تسقطُ دائماً: نجمةٌ صادقةٌ واحدةٌ خيرٌ من عشرٍ مزيفة — والصدقُ يهدي إلى البر.',apply:'راجع نفسك: هل «نفختَ» إنجازاً يوماً لتبدو أفضل؟ صحّحها اليوم، وتذكّر: نجمة صادقة خير من عشر مزيفة.'},

{n:20,t:'جبلُ جزءِ عمّ',ic:'📗',age:'٦ سنوات',loc:'مكتب البيت',corner:'quran',goal:'انطلاق مشروع الحفظ المنظم: ورد يومي صغير ثابت خير من حماس متقطع',chars:['مريم','صلاح الدين','أيوب'],
scenes:[
{h:'م١ · داخلي — غرفة الجلوس، بعد الفجر',d:'ستارة تُزاح عن الجدار قرب مكتب صلاح الدين: لوحة كبيرة رسمتها مريم — جبل أخضر عظيم من ٣٧ درجة، على كل درجة اسم سورة من الناس صعوداً إلى النبأ، وعلى القمة علم ذهبي صغير.',dlg:[['مريم','هذا جبلُك يا صلاح الدين: جبلُ جزءِ عمّ! حفظتَ الفاتحةَ والقصارَ وأنتَ صغير… واليومَ نبدأ التسلقَ الحقيقي: سورةٌ فوقَ سورة، حتى نغرسَ العلمَ في القمة!'],['صلاح الدين','(يعد الدرجات بإصبعه مبهوراً) سبعٌ وثلاثون! سأتسلقُهُ كلَّهُ هذا الأسبوع!'],['مريم','(تضحك) وهنا أولُ قوانينِ الجبل…']],vo:'ظننتُ الحفظَ سباقاً سريعاً. وكانت أمي تعرفُ أنه ليس سباقاً أصلاً… بل مشياً طويلاً جميلاً لا يتوقف.'},
{h:'م٢ · داخلي — المكتب، شرح القاعدة الذهبية',d:'مريم تمسك كوبين: كوب ماء صغير وإبريق ضخم. في الشرفة نبتتان متطابقتان.',dlg:[['مريم','انظر: هذه النبتةُ سأسقيها كلَّ يومٍ كوباً صغيراً. وهذه سأغرقُها اليومَ بالإبريقِ كلِّهِ ثم أنساها أسبوعين. أيهما ستعيش؟'],['صلاح الدين','الأولى طبعاً! الثانيةُ ستغرقُ ثم تعطش!'],['مريم','وهكذا الحفظ! قال رسولُ اللهِ ﷺ: أحبُّ الأعمالِ إلى اللهِ أدومُها وإن قلّ. قانونُنا: خمسُ آياتٍ كلَّ يومٍ بعد الفجر — لا أكثرَ في يومِ الحماس، ولا صفرَ في يومِ الكسل.'],['صلاح الدين','خمسٌ فقط؟! أنا أستطيعُ عشرين!'],['مريم','(تبتسم ابتسامة العارفين) سنرى يا متسلقي الصغير… سنرى.']]},
{h:'م٣ · داخلي — مونتاج أسبوعين',d:'مونتاج: فجر إثر فجر — خمس آيات، تلوين درجة على الجبل، نجمة. ثم يوم مطر وكسل: يتقلب في سريره ويرفض القيام. المساء: يقف أمام الجبل — درجة اليوم بيضاء فارغة وسط الأخضر، تؤلم عينه.',dlg:[['صلاح الدين','(يفرك عينيه أمام اللوحة) الفراغُ… قبيح. غداً سأحفظُ عشراً وأسدُّ الفجوة!']]},
{h:'م٤ · داخلي — فجر اليوم التالي، درس التعويض المتعجل',d:'يحاول حفظ عشر آيات دفعة واحدة: يخلط آيات الغاشية بالأعلى، يتلعثم، يضرب المصحف الصغير بكفه إحباطاً. مريم تدخل بهدوء وتغلق المصحف برفق.',dlg:[['مريم','مهلاً يا حبيبي… الجبلُ لا يُقفزُ درجتين. الذي فاتَهُ يومٌ لا يعوضُهُ بالتخليط… يعوضُهُ بالرجوعِ إلى النظام. خمسُ آياتِ اليوم فقط — والفجوةُ نتركُها بيضاءَ تذكرنا: الانقطاعُ له ثمن.'],['صلاح الدين','(يهدأ ويفتح المصحف) خمسٌ… متقنة.'],['مريم','متقنةٌ ومفهومة! والآن: ماذا تعني عاملةٌ ناصبة؟']],vo:'بقيتْ تلكَ الدرجةُ البيضاءُ في جبلي إلى اليوم — لم نلوِّنْها أبداً. كانت أصدقَ معلمٍ في اللوحة: تصرخُ بصمتٍ كلَّ فجر: لا تنقطعْ… لا تنقطع.'},
{h:'م٥ · داخلي — بعد شهرين، أول قمة صغيرة',d:'احتفال عائلي مصغر: سورة الشمس تُلوَّن — ثلث الجبل اكتمل. أيوب يرفع صلاح الدين ليغرس بنفسه علماً صغيراً أحمر في منتصف الطريق، ويوسف الصغير يصفق.',dlg:[['أيوب','ثلثُ الجبل! أتعرفُ كم خمسةً صنعتْ هذا؟ ستون فجراً يا بطل… قطرةٌ فقطرةٌ يمتلئُ النهر.'],['صلاح الدين','(ينظر للقمة البعيدة ثم يبتسم) والقمةُ القادمة… تبارك؟ ثم الجبالُ كلُّها؟'],['مريم','(تتبادل نظرة بعيدة مع أيوب) القرآنُ كلُّهُ يا صلاح الدين… جبلٌ فوقَ جبل، حتى تقفَ يوماً حيثُ لا تتخيلُ الآن.']]}],
msg:'أحبُّ الأعمالِ إلى الله أدومُها وإن قلّ: خمسُ آياتٍ كل فجرٍ تغلبُ عشرين في يوم الحماس — والانقطاعُ وحده هو الخصم.',apply:'ابدأ وردك الثابت: ٥ آيات (أو ٣) كل يوم بعد صلاة الفجر أو قبل النوم — وارسم جبلك وعلّم تقدمك.'},

{n:21,t:'مُروا أولادَكم',ic:'🕌',age:'٧ سنوات',loc:'بيت العائلة',corner:'ibada',goal:'السابعة سن أمر الصلاة: ركن الصلاة في البيت وبدء المتابعة الحانية',chars:['صلاح الدين','أيوب','مريم','يوسف'],
scenes:[
{h:'م١ · داخلي — غرفة صلاح الدين، صباح عيد ميلاده السابع',d:'يفتح عينيه فيجد زاوية غرفته قد تحولت في الليل: سجادة صلاة خضراء بحجمه تماماً، ساعة مواقيت صغيرة على الجدار، مصحف على حامل خشبي، ولوحة مربعات أنيقة: «صلواتي الخمس × ٣٠ يوماً».',dlg:[['صلاح الدين','(يقف مذهولاً بملابس نومه) ما هذا؟!'],['أيوب','(من الباب مع مريم) مباركٌ عليكَ الوسام يا رجل! اليومَ سبعُ سنوات… واليومَ يشملُكَ أمرُ رسولِ اللهِ ﷺ: مُروا أولادَكم بالصلاةِ وهم أبناءُ سبعِ سنين. لم تعد تصلي «تقليداً لنا»… من اليومِ تصلي لأنكَ مأمورٌ من النبيِّ نفسِه!'],['صلاح الدين','(يقف مستقيماً كجندي) النبيُّ ﷺ… أمرني أنا؟!']],vo:'أذكرُ تلك القشعريرة: أمرٌ نبويٌّ باسمي! لم تكن الصلاةُ يومَها عبئاً… كانت وساماً على صدرِ طفلٍ في السابعة.'},
{h:'م٢ · داخلي — أسبوع الحماس، مونتاج مبهج',d:'مونتاج: يؤذّن في البيت بأعلى صوته ويوسف (٣ سنوات) يقلده خلفه كصدى أعوج. يفرش سجادته قبل الأذان بعشر دقائق. يوقظ أباه لصلاة الفجر — الأب يفتح عيناً واحدة مبتسماً. المربعات الأولى في اللوحة تمتلئ نجوماً.',dlg:[['أيوب','(لمريم هامساً وهما يراقبانه يصلي) اللهم بارك… لكن تعرفين أن الحماسَ الأولَ يفتر. المهمُّ ماذا نفعلُ نحن عندها.'],['مريم','نتذكرُ الحديث: مُروا… ولم يقل: اصرخوا.']]},
{h:'م٣ · داخلي — الأسبوع الثالث، فتور العصر',d:'شتاء. صلاح الدين عائد من المدرسة متعباً، يستلقي أمام مدفأة الغرفة بلعبته. ساعة المواقيت ترن للعصر… يتجاهلها. مريم تراه ولا تصرخ: تتوضأ هي، وتفرش سجادتها بجانب سجادته الفارغة، وتصلي. صوت خشوعها يملأ الغرفة. الطفل يرفع عينيه من اللعبة… ينظر للسجادة الخضراء الفارغة بجانب أمه.',dlg:[['صلاح الدين','(ينهض متثاقلاً ويتوضأ ويقف بجانبها في صلاته هو)…'],['مريم','(بعد التسليم، تمسح رأسه بلا كلمة لوم واحدة) أتدري ماذا قال ربُّنا عن العصر؟ حافظوا على الصلواتِ والصلاةِ الوسطى… العلماءُ قالوا: هي العصر! لأنها تأتي وقتَ التعبِ واللعب… فمن حافظَ عليها فهو من الحافظين حقاً.'],['صلاح الدين','وقتَ التعبِ واللعب… (ينظر للعبته) اللهُ يعرفُ أنها صعبة… ولذلك جعلَها الوسطى؟'],['مريم','ولذلك أجرُها أعظم.']],vo:'لم توبخني أمي يومَها… فرشتْ سجادتَها وحسب. وكان منظرُ سجادتي الفارغةِ بجانبِها أبلغَ من ألفِ محاضرة. هكذا يُربّى الناس: بالقدوةِ التي تُرى، لا بالصوتِ الذي يُرفع.'},
{h:'م٤ · داخلي — نهاية الشهر، جردة اللوحة',d:'العائلة أمام لوحة «صلواتي الخمس»: شهر كامل — معظمه نجوم، وسبعة مربعات فارغة متناثرة، وأسبوع أخير كامل بلا فراغ واحد.',dlg:[['أيوب','انظر لأسبوعِكَ الأخير: خمسٌ وثلاثون صلاةً بلا ثقبٍ واحد! أتعرفُ ماذا يعني هذا؟ أنَّ العادةَ انعقدت. الصلاةُ الآن ليست شيئاً تفعلُه… صارت شيئاً منك، مثلَ اسمِك.'],['صلاح الدين','(يتأمل المربعات الفارغة السبعة) وهذه الثقوب؟'],['أيوب','ذكرياتُ التدريب. البطلُ لا يخجلُ من سقطاتِ تعلُّمِه… يخجلُ فقط من التوقف.']]},
{h:'م٥ · داخلي — ليلاً، لقطة ختامية',d:'البيت نائم. الكاميرا تمر على ركن الصلاة الصغير المضاء بنور خافت: السجادة الخضراء مستقيمة، وفوقها ورقة كتبها الطفل بخطه وعلقها بنفسه: «موعدي مع ربي: ٥ مرات كل يوم».',vo:'من ذلك الركنِ الصغيرِ في مانشستر… إلى محاريبَ سترونها في آخرِ هذه القصة. كلُّ شيءٍ بدأ بسجادةٍ بحجمِ طفل، وأمرٍ نبويٍّ لابنِ سبع، وأمٍّ تصلي بجانبي بدلَ أن تصرخَ فيّ.'}],
msg:'مُروا أولادكم بالصلاة لسبع: بالتشريف لا بالتعنيف — سجادة خاصة ولوحة متابعة وقدوة تُرى تصنع مصلياً للعمر.',apply:'جهّز ركن صلاتك: سجادة وموضع ثابت ولوحة الصلوات الخمس — وسجّل أسبوعك، والفائز من لا فراغ عنده.'},

{n:22,t:'أبطالُ الفجر',ic:'🌅',age:'٧ سنوات',loc:'البيت ومسجد النور — شتاء',corner:'ibada',goal:'فجر الشتاء مدرسة الأبطال — «بشّر المشّائين في الظُّلَم إلى المساجد بالنور التام يوم القيامة»',chars:['صلاح الدين','أيوب','الشيخ إدريس'],
scenes:[
{h:'م١ · داخلي — غرفة صلاح الدين، الخامسة فجراً',d:'ظلام دامس ومطر على الزجاج. منبه صغير يرن. يد صغيرة تخرج من تحت البطانية وتكتمه… ثم يتذكر: طلب هو بنفسه أمسِ أن يرافق أباه لفجر المسجد. معركة صامتة كوميدية: يخرج قدماً من البطانية فيلسعها البرد فيعيدها. يسمع خطوات أبيه في الممر.',dlg:[['صلاح الدين','(يهمس لنفسه تحت البطانية) أنتَ طلبتَها يا صلاح الدين… أبطالُ الفجرِ لا تحبسُهم بطانية! (يقفز دفعة واحدة) بسم الله!']],vo:'أعترفُ لكم: أصعبُ أعدائي في السابعةِ لم يكن وحشاً ولا ظلاماً… كان بطانيتي الدافئةَ في فجرِ الشتاء. ومن هزمَها… هزمَ بعدَها كلَّ شيء.'},
{h:'م٢ · خارجي — الشارع إلى المسجد، فجر مثلج',d:'أب وابنه يمشيان في شارع خالٍ تماماً، أنفاسهما بخار، الثلج يهبط ناعماً تحت أضواء المصابيح الصفراء. الطفل ملفوف حتى عينيه.',dlg:[['صلاح الدين','(من تحت الكوفية) بابا… لماذا لا يوجدُ أحدٌ في الشارع؟'],['أيوب','لأن هذه ساعةُ الكنوزِ المخفية! اسمع هذا: قال رسولُ اللهِ ﷺ: بشِّرِ المشّائينَ في الظُّلَمِ إلى المساجدِ بالنورِ التامِّ يومَ القيامة. كلُّ خطوةٍ تخطوها الآن في هذا الظلام… تتحولُ نوراً ينتظرُكَ هناك.'],['صلاح الدين','(يتوقف… ثم يبدأ يعد خطواته بصوت مسموع) واحدة، اثنتان، ثلاث…! بابا امشِ من الطريقِ الأطول!'],['أيوب','(يضحك من قلبه في الشارع الفارغ) هذه أولُ مرةٍ يطلبُ فيها أحدٌ تطويلَ طريقِ الفجر!']]},
{h:'م٣ · داخلي — مسجد النور، صلاة الفجر',d:'المسجد شبه خالٍ: سبعة رجال فقط في الصف الأول، أنفاسهم ما زالت باردة. الشيخ إدريس يلتفت قبل الإقامة فيرى الطفل بين الرجال، فيتهلل وجهه.',dlg:[['الشيخ إدريس','(بصوته العميق) سبعةُ رجال… وأسد! يا جماعة، أفسحوا للبطل مكانَهُ في الصف — فمن غلبَ فراشَهُ في مثلِ هذا الفجر، فهو منا وأفضل.'],['صلاح الدين','(يهمس لأبيه وهو يقف في الصف) بابا… لماذا نحن قليلون؟'],['أيوب','(هامساً) لأن هذا صفُّ الخاصة يا بني… ركعتا الفجرِ خيرٌ من الدنيا وما فيها — والكنوزُ الغاليةُ لا يزاحمُ عليها إلا القليل.']],vo:'سبعةُ رجالٍ وطفل، في مسجدٍ صغيرٍ تحاصرُهُ الثلوج… لكني ما شعرتُ بدفءٍ كذلك الدفءِ في حياتي. عرفتُ لاحقاً اسمَه: دفءُ الصف.'},
{h:'م٤ · داخلي — المسجد، بعد الصلاة',d:'أثناء الذكر، رأس الطفل يثقل على كتف أبيه… ويغفو تماماً. لقطة حانية: أيوب يحمله على كتفه ويخرج به، والشيخ إدريس يضع في جيب الطفل النائم تمرتين ويربت رأسه.',dlg:[['الشيخ إدريس','(هامساً لأيوب) نامَ الأسد… احمله برفق. يا أيوب، هذه الفجرياتُ التي يظنُّها الناسُ صغيرة — هي التي تُبنى منها القاماتُ الكبيرة. استمرّا.']]},
{h:'م٥ · داخلي — المدرسة، صباح اليوم نفسه',d:'حصة الصباح. المعلمة تسأل: من فعل شيئاً شجاعاً هذا الأسبوع؟ أيادٍ ترتفع: ركبت الدراجة بلا عجلات! لمست عنكبوتاً! — صلاح الدين يرفع يده أخيراً.',dlg:[['صلاح الدين','أنا استيقظتُ قبل الشمس… ومشيتُ في الثلجِ والظلامِ إلى المسجد. أبي يقول: كلُّ خطوةٍ نورٌ يومَ القيامة. عددتُ خطواتي: أربعُمئةٍ وسبعَ عشرةَ خطوة!'],['المعلمة كلارك','(بعد لحظة صمت متأثرة) أظنُّ… أن هذه أشجعُ إجابةٍ سمعتُها في هذا الصف.']],vo:'أربعُمئةٍ وسبعَ عشرةَ خطوة… ما زلتُ أذكرُ الرقم. يا أصدقائي: الفجرُ مدرسةُ الأبطالِ الحقيقية — من انتصرَ فيه على نفسِهِ أولَ النهار، لم تهزمْهُ الدنيا آخرَه.'}],
msg:'بشّرِ المشّائين في الظُّلَم إلى المساجد بالنور التام: من غلب بطانيته فجرَ الشتاء… غلب بعدها كلَّ شيء.',apply:'تحدي أبطال الفجر: ثلاثة أيام متتالية صلِّ الفجر في وقته (في المسجد إن استطعت) — وسجّل شعورك بعد كل مرة.'},

{n:23,t:'حفلةُ عيدِ الميلاد',ic:'🎂',age:'٧ سنوات',loc:'المدرسة وبيت العائلة',corner:'aqeeda',goal:'الهوية بلا عدوانية: نحترم الناس ولا نذوب فيهم — لنا أعيادنا ولهم أعيادهم',chars:['صلاح الدين','توم','المعلمة كلارك','أيوب','مريم'],
scenes:[
{h:'م١ · داخلي — الصف، موسم ديسمبر',d:'الصف تحول: زينة حمراء وخضراء، شجرة مزينة في الزاوية، أناشيد موسمية تتسرب من الممر. المعلمة توزع دعوات حفلة نهاية الفصل. توم يلوّح بدعوته متحمساً.',dlg:[['توم','ستأتي؟ قل إنك ستأتي! سيكون هناك كعك وألعاب و…أغاني العيد وقصة القديس!'],['صلاح الدين','(يمسك الدعوة وينظر إليها طويلاً… فرح وحيرة يتصارعان على وجهه) أنا… أسألُ أبي وأمي أولاً.']],vo:'كانت أصعبَ ورقةٍ حملتُها في السابعة: دعوةٌ ملونةٌ جميلة… تسحبُني من جهة، وشيءٌ في صدري يشدُّني من جهةٍ أخرى. من أنا وسطَ كلِّ هذه الزينةِ التي ليست زينتي؟'},
{h:'م٢ · داخلي — البيت، مجلس الميزان',d:'العشاء. الدعوة موضوعة وسط الطاولة كقضية كبرى. الوالدان لا يستنكران ولا يتحمسان — يفتحان حواراً هادئاً.',dlg:[['صلاح الدين','كلُّ الصفِّ سيذهب… إن رفضتُ سيقولون: غريب! وإن ذهبتُ… هم يحتفلون بشيءٍ نحن لا نؤمنُ به. ماذا أفعل؟'],['أيوب','سؤالُكَ نفسُهُ يا صلاح الدين… علامةُ أنك كبرت. اسمع الميزانَ الذهبيَّ الذي لن يخذلَكَ أبداً: نحسنُ إلى الناسِ جميعاً ونحترمُهم — ولا نذوبُ فيهم. جارُنا نحبُّهُ ونهاديه، أما عيدُ عبادتِهم فليس عيدَنا: لكلِّ قومٍ عيد، وعيدُنا الفطرُ والأضحى.'],['مريم','والاحترامُ بلا ذوبان يعني: لا نسخرُ من عيدِهم أبداً، ولا نشاركُ في شعائرِه. نعتذرُ بلطف… ونبقى أصدقاءَهم أوفياء.']]},
{h:'م٣ · داخلي — المدرسة، الاعتذار اللبق',d:'صلاح الدين يقترب من توم في الاستراحة، ممسكاً وراء ظهره شيئاً ملفوفاً.',dlg:[['صلاح الدين','توم… لن أحضرَ الحفلة. نحن لا نحتفلُ بها في ديننا — عندنا عيدان تعرفُهما: يومَ أهديتُكَ البالون! لكني… (يخرج الهدية) أحضرتُ لك هديةً الآن، بلا مناسبة. لأنكَ صديقي كلَّ السنة، لا يومَ الحفلةِ فقط.'],['توم','(يفتحها: مجسم طائرة كان يتمناها — يذهل) بلا مناسبة؟!… أنتَ أغربُ صديقٍ عندي يا صلاح الدين — وأفضلُهم! (يفكر) إذن أنا أيضاً سأهديكَ في عيدِكم أنتم!'],['صلاح الدين','(يضحك) اتفقنا — عيدي بعد رمضان، لا تنسَ!']],vo:'اكتشفتُ يومَها سراً: حينَ تعتذرُ بعزةٍ وحبٍّ معاً… لا تخسرُ أحداً. الذي يخسرُ هو من يذوبُ خجلاً، أو يجرحُ غروراً.'},
{h:'م٤ · داخلي — الصف، يوم الحفلة',d:'الصف يحتفل. صلاح الدين ليس هناك — قطع متوازٍ: هو في بيته يساعد أمه في تجهيز صناديق طعام للمحتاجين (مشروع المسجد الشتوي)، يلصق على كل صندوق بطاقة رسمها بنفسه. المعلمة كلارك تسأل توم عن غيابه فيشرح بفخر غريب.',dlg:[['توم','صلاح الدين لا يحتفلُ بعيدِنا — عندهم عيدان خاصان. لكنه أعطاني هديةً «بلا مناسبة»! وهو الآن يساعدُ الفقراءَ مع أمه. أليس هذا… نوعاً من الاحتفالِ أيضاً؟'],['المعلمة كلارك','(تبتسم بتأمل) بلى يا توم… من أجملِ الأنواع.']]},
{h:'م٥ · خارجي — بين البيتين، ليلاً',d:'لقطة رمزية ختامية: نافذة آل ويلسون تلمع فيها نجمة عيدهم الفضية… ونافذة بيت صلاح الدين يلمع فيها هلاله المضيء الذي علقه منذ رمضان. بينهما السور القصير المشترك، وعليه أثر أقدام الطفلين في الثلج متجاورة.',vo:'نجمتُهم في نافذتِهم… وهلالُنا في نافذتِنا… وبينهما سلامٌ وصحنُ كعك. هكذا علمتني مانشستر أغلى دروسِ الهوية: كنْ نفسَكَ بلا خجل… وكنْ لجارِكَ بلا حدود. فالشجرةُ الثابتةُ الجذور… هي وحدَها التي تمدُّ أغصانَها للجميع.'}],
msg:'الميزان الذهبي: نحسن إلى الناس ونحترمهم ولا نذوب فيهم — لكل قومٍ عيد وعيدُنا الفطر والأضحى.',apply:'احفظ الميزان: «أحسنُ إلى الجميع، وأعتز بعيدي» — واذكر عيدَي المسلمين ومتى يأتيان هذا العام.'},

{n:24,t:'الجنيهُ الضائع',ic:'💷',age:'٧ سنوات',loc:'ساحة المدرسة',corner:'social',goal:'الأمانة فيما لا يراك فيه أحد — اللقطة تُسلَّم ولا تُملَك',chars:['صلاح الدين','المعلمة كلارك','الطفلة إيمي','مريم'],
scenes:[
{h:'م١ · خارجي — ساحة المدرسة، الاستراحة الكبرى',d:'صخب أطفال. صلاح الدين يلاحق كرة نحو سور الساحة… فيتجمد: عند قاعدة السور ورقة نقدية مطوية — خمسة جنيهات. يلتقطها. لا أحد رآه. لقطة قريبة: الورقة في كفه الصغيرة… وفي خياله يلمع فوراً مجسم السفينة المعروض في واجهة المكتبة منذ شهر — ثمنه خمسة جنيهات بالضبط.',vo:'خمسةُ جنيهات. لا أحدَ رأى. والسفينةُ التي أحلمُ بها منذ شهرٍ ثمنُها خمسةُ جنيهاتٍ بالضبط… كأنَّ الدنيا تهمسُ لي: خذها، إنها هديةُ الحظ! وبدأتْ أطولُ خمسُ دقائقَ في طفولتي.'},
{h:'م٢ · خارجي — الساحة، الصراع الصامت',d:'مشهد شبه صامت بزمن حقيقي: يدور حول الساحة والورقة تحرق جيبه. يمر أمام أصدقائه ولا يسمعهم. يجلس على مقعد. يخرجها، يعدّها، يعيدها. فلاش سريع: صوت المعلمة يوم النجوم «النجوم المزيفة تسقط»… صوت أمه «الولد الصادق لا يُشترى»… ثم فلاش أقوى: أبوه يحكي عن النبي ﷺ قبل النبوة — والناس تترك عنده الأمانات لأنه «الأمين».',dlg:[['صلاح الدين','(يقف فجأة ويشد قبضته على الورقة) هي ليست هديةَ الحظ… هي أمانةُ واحدٍ يبكي عليها الآن. (يمشي بخطوات سريعة نحو مبنى المدرسة قبل أن يغير رأيه)']]},
{h:'م٣ · داخلي — غرفة المعلمين',d:'يسلّم الورقة للمعلمة كلارك ويشرح مكانها بدقة. ترمقه بنظرة طويلة.',dlg:[['صلاح الدين','وجدتُها عند السور. ربما سقطت من أحدٍ ما… أنا لم أصرفْ منها شيئاً — عدّيها!'],['المعلمة كلارك','(تضحك وتعدها مازحة) خمسةٌ كاملة! سأعلنُ عنها. لكن قل لي… لماذا لم تأخذْها وأنتَ وحدك؟'],['صلاح الدين','(إجابة فورية بلا تفكير) لأني لم أكن وحدي… اللهُ يراني.']],vo:'رأيتُها تكتبُ شيئاً في دفترِها بعدما خرجت. عرفتُ بعد سنواتٍ أنها كتبت: «هذا الطفلُ يحملُ رقيباً في قلبِه… ليتَ صفي كلَّهُ مثلُه».'},
{h:'م٤ · داخلي — طابور الصباح، اليوم التالي',d:'المعلمة تعلن عن المبلغ. من آخر الطابور تنفجر طفلة صغيرة (إيمي، الصف الأول) بالبكاء وتتقدم: نقود رحلة الغد التي أضاعتها — كانت ستبقى وحدها في المدرسة بينما يذهب صفها لحديقة الحيوان. تستلمها وتلتفت باحثة عمن وجدها.',dlg:[['إيمي','(بعينين دامعتين لصلاح الدين) أنتَ وجدتَها؟… كنتُ سأحرمُ من الرحلة! شكراً! شكراً!'],['صلاح الدين','(محرج من فرحتها، يهز رأسه)… سلمي على الزرافةِ من أجلي.']]},
{h:'م٥ · داخلي — البيت، مساءً',d:'يحكي لأمه. مريم تفتح حصالته أمامه وتضع فيها جنيهاً واحداً.',dlg:[['صلاح الدين','جنيه؟ على ماذا؟'],['مريم','ليس مكافأةً على الأمانة — الأمانةُ لا تُشترى. هذه دفعةٌ أولى نحو سفينتِك… تجمعُها حلالاً كما تعرف. المهم: بمَ شعرتَ حين بكت الطفلةُ فرحاً؟'],['صلاح الدين','(يفكر بعمق)… شعرتُ أن صدري أوسعُ من الساحة. أحلى من السفينة… أحلى حتى من عشرِ سفن!'],['مريم','هذا اسمُهُ حلاوةُ الأمانة يا حبيبي… من ذاقَها مرة، لم يبعْها بمالِ الدنيا.']],vo:'اشتريتُ السفينةَ بعد شهرين بمالي الحلال… وكسرتْها الأيامُ ونسيتُها. أما وجهُ إيمي الباكي فرحاً… فما زالَ في قلبي إلى اليوم. الأشياءُ تبلى يا أصدقائي — والأمانةُ لا تبلى.'}],
msg:'الأمانةُ ما حفظتَهُ حين لا يراك أحد — «اللهُ يراني» تجعل اللقطةَ تصل صاحبها وصدرَك أوسعَ من الدنيا.',apply:'إن وجدت شيئاً ليس لك (نقوداً، قلماً، لعبة) فسلّمه فوراً لصاحبه أو للمسؤول — جرّب حلاوة الأمانة ولو مرة.'},

{n:25,t:'مكتبةُ أبي',ic:'📚',age:'٧ سنوات',loc:'غرفة مكتب الأب',corner:'academy',goal:'حب الكتاب والقراءة: أمة «اقرأ» لا تعيش بلا كتب',chars:['صلاح الدين','أيوب','مريم'],
scenes:[
{h:'م١ · داخلي — ممر البيت، عصر يوم ممطر',d:'ملل يوم مطير. صلاح الدين يتجول في البيت… فيجد باب مكتب أبيه موارباً لأول مرة. يدفعه بأصابعه: جدار كامل من الكتب حتى السقف — أطياف ألوان وأحجام، وسلم خشبي صغير متحرك. يدخل كمن دخل كهف كنوز.',dlg:[['صلاح الدين','(يهمس مبهوراً وهو يدير رأسه) كلُّ هذه… كتب؟!'],['أيوب','(من كرسيه في الزاوية، لم يكن نائماً) تفضل يا زائري العزيز… أهلاً بك في أغنى غرفةٍ في البيت.']],vo:'كنتُ أظنُّ غرفةَ أبي مخزناً ممنوعاً. فإذا هي المكانُ الذي سيغيّرُ خريطةَ حياتي… غرفةٌ جدرانُها من ورق، وأبوابُها إلى كلِّ مكان.'},
{h:'م٢ · داخلي — المكتب، حكاية «اقرأ»',d:'أيوب يجلسه على السلم الخشبي كأنه عرش، ويحكي بأسلوب مشوق مع إضاءة خافتة.',dlg:[['أيوب','أتعرفُ أولَ كلمةٍ نزلتْ من السماءِ على نبيِّنا ﷺ؟ لم تكن: صلِّ. ولا: صُم. كان جالساً في غارٍ اسمُهُ حراء، فجاءَهُ جبريلُ وقال له كلمةً واحدة: اقرأ!'],['صلاح الدين','اقرأ؟! قبل كلِّ شيء؟!'],['أيوب','قبلَ كلِّ شيء. لأن أمةً لا تقرأ… لا تعرفُ ربَّها حقَّ المعرفة، ولا تبني، ولا تقود. نحن أمةُ اقرأ يا صلاح الدين — هذا اسمُنا الحقيقي.']]},
{h:'م٣ · داخلي — المكتب، رحلة بغداد وقرطبة',d:'أيوب يفتح كتاباً مصوراً ضخماً: رسومات مكتبة بيت الحكمة، وقرطبة القديمة.',dlg:[['أيوب','قبل ألفِ سنة، حين كانت أوروبا كلُّها لا تجدُ إلا بضعَ مئاتٍ من الكتب… كانت في بغدادَ مكتبةٌ فيها مئاتُ الآلاف! وكان الخليفةُ يزنُ الكتابَ المترجمَ ذهباً — الكتابُ في كفة، والذهبُ في كفة!'],['صلاح الدين','(يمسك أقرب كتاب ويزنه بيديه) هذا الكتاب… كان يساوي كنزاً؟!'],['أيوب','وما زال. الذهبُ يشتري الأشياء… والكتابُ يشتري العقول. والأمةُ التي باعتْ كتبَها… باعتْ مكانَها في مقدمةِ الدنيا.']],vo:'يومَها فهمتُ لماذا يدَّخرُ أبي من راتبِهِ ليشتريَ الكتب… كان يشتري لنا تذاكرَ عودةٍ إلى المقدمة.'},
{h:'م٤ · داخلي — المكتب، تدشين الرف',d:'أيوب يفرغ رفاً كاملاً في متناول يد الطفل، ويثبت عليه لوحة خشبية صغيرة: «رفُّ صلاح الدين». يضع عليه أول كتابين: قصص الأنبياء للصغار، وكتاب عجائب المخلوقات.',dlg:[['أيوب','هذا رفُّك — يكبرُ بكتابٍ كلَّ شهر. لكن للكتابِ عندنا أدبٌ: يُمسَكُ بيدين نظيفتين، ولا يُطوى وجهُهُ على بطنِه، ولا يُترَكُ مفتوحاً مقلوباً كالخيمةِ الساقطة، ويعودُ لمكانِهِ كما يعودُ المسافرُ لبيتِه.'],['صلاح الدين','(يحمل الكتابين بيدين حريصتين كأنه يحمل يوسف الرضيع) وأقرؤهما متى؟'],['مريم','(تظهر عند الباب حاملة صينية شاي وثلاثة كتب لها) الآن! عندنا قانونٌ جديدٌ من الليلة: ربعُ ساعةِ القراءة — البيتُ كلُّهُ يقرأُ معاً، حتى يوسف يقلّبُ مصوَّرَه.']]},
{h:'م٥ · داخلي — غرفة الجلوس، طقس القراءة الأول',d:'مشهد ختامي دافئ: المدفأة تشتعل، المطر على النافذة، والعائلة كلها صامتة تقرأ — الأب كتابه، الأم كتابها، صلاح الدين مستلقٍ على بطنه مع قصص الأنبياء، ويوسف (٣ سنوات) يقلّب كتاباً مصوراً بالمقلوب. ساعة الحائط تتك في الخلفية.',vo:'ربعُ ساعةٍ في اليوم… تظنونَها قليلة؟ ربعُ ساعةٍ في اليومِ تعني تسعينَ ساعةً في السنة — وتسعونَ ساعةً تبني في رأسِ طفلٍ مدينةً كاملة. يا أهلَ البيوت: أطفئوا شاشةً واحدة… وأشعلوا هذا الطقسَ الليلة.'}],
msg:'نحن أمةُ «اقرأ»: الكتاب يشتري العقول، وربعُ ساعة قراءة يومياً يبني في رأس الطفل مدينة كاملة.',apply:'أنشئ رفّك الخاص ولو بثلاثة كتب، وقرروا في البيت «ربع ساعة القراءة» يومياً — الكل يقرأ في وقت واحد.'},

{n:26,t:'أختٌ اسمُها شام',ic:'👶',age:'٧ سنوات',loc:'بيت العائلة',corner:'heart',goal:'الرحمة بالصغير قيادة: الأخ الكبير راعٍ ومسؤول — وهذه المرة بلا غيرة',chars:['صلاح الدين','يوسف','أيوب','مريم','شام (رضيعة)'],
scenes:[
{h:'م١ · داخلي — باب البيت، العودة من المستشفى',d:'إعادة بصرية مقصودة لمشهد الحلقة السادسة: الباب يفتح، مريم تدخل حاملة رضيعة، ضجة أقارب وجيران. لكن الكاميرا هذه المرة تجد صلاح الدين (٧ سنوات) واقفاً في المقدمة لا في الزاوية — يحمل لافتة رسمها: «أهلاً شام» وبجانبه يوسف (٣ سنوات) عابس مقطب متجهم… في الزاوية.',vo:'هل تذكرونَ الطفلَ الغيورَ الذي أرادَ إعادةَ أخيهِ من حيثُ جاء؟ كبرَ ذلك الطفلُ وتعلمَ الدرس. لكنَّ التاريخَ قررَ أن يعيدَ نفسَه… في وجهٍ آخرَ صغيرٍ عابس.'},
{h:'م٢ · داخلي — غرفة الجلوس، رصد الغيرة الجديدة',d:'يوسف يجرب حيل الحلقة السادسة نفسها: يقفز، يغني بأعلى صوته، يقلب كوباً «بالخطأ». صلاح الدين يراقبه ويتعرف على نفسه القديمة. يتبادل نظرة مع أبيه — أيوب يهم بالنهوض، فيشير له صلاح الدين بثقة: دعها لي.',dlg:[['صلاح الدين','(هامساً لأبيه) أعرفُ هذا المرضَ يا بابا… أنا مخترعُه! واسمحْ لي — عندي الدواء.']]},
{h:'م٣ · داخلي — غرفة يوسف، ليلاً',d:'المشهد الأجمل: صلاح الدين يعيد مع أخيه الحوار الذي أجراه أبوه معه قبل ثلاث سنين — بنفس الجلسة على الأرض ونفس فتح الذراعين.',dlg:[['صلاح الدين','يوسف… أتعرفُ على اسمِ من سُميت؟ نبيٌّ كان له إخوةٌ كبار… غاروا منه فرموهُ في بئر!'],['يوسف','(من بين دموعه) بئر؟! ولماذا؟'],['صلاح الدين','لأن الغيرةَ تُعمي القلب. وأنا يا يوسف… غِرتُ منكَ يومَ وُلدت! نعم أنا! وكدتُ أطلبُ إعادتَك! لكنَّ بابا علمني سراً: أن أكونَ الأخَ الحامي. والآن جاءَ دورُك: شام صغيرةٌ وضعيفة… أتكونُ حارسَها الثاني معي؟ الحراسُ يا يوسف لا يغارون من القلعة… هم يحمونها!'],['يوسف','(يمسح دموعه ويفكر بجدية الثلاث سنين)… حارس؟ مثلُ الأبطال؟ (يقف فجأة) أين القلعة؟!']],vo:'في تلكَ الليلةِ فهمتُ أعظمَ أسرارِ التربية: الدرسُ الذي تتعلمُهُ حقاً… هو الدرسُ الذي تُعلِّمُه. كان أبي يزرعُ فيَّ يومَها شجرةً… لم أعرف أنها ستثمرُ في يدي أنا.'},
{h:'م٤ · داخلي — غرفة الرضيعة، بعد لحظات',d:'الأخوان يدخلان على أطراف الأصابع. يوسف يضع بجانب شام النائمة أغلى ما يملك: ديناصوره المطاطي الأخضر. صلاح الدين يغطيهما بالبطانية الزرقاء العتيقة — نفسها التي أهداها ليوسف يوم ولد، والتي أهداه إياها أبوه قبلها.',dlg:[['يوسف','(هامساً للرضيعة) يا شام… أنا يوسف، حارسُكِ الثاني. هذا التنينُ سيحرسُكِ عندما أنام أنا.'],['مريم','(من عتبة الباب لأيوب، دموعها تلمع — تكرار المشهد القديم بأدوار جديدة) انظر… البطانيةُ الزرقاءُ وصلت للثالث.'],['أيوب','(هامساً) هكذا تسري التربيةُ في البيوت يا مريم… بطانيةً بعد بطانية.']]},
{h:'م٥ · داخلي — المطبخ، سؤال الاسم',d:'إفطار الصباح. صلاح الدين يسأل السؤال المؤجل.',dlg:[['صلاح الدين','ماما… يوسف اسمُ نبي، وأنا اسمُ بطل. وشام؟ اسمُ ماذا؟'],['مريم','اسمُ أرضٍ مباركة! بلادُ الشام: فيها فلسطينُ والقدسُ التي على جدارِنا، وفيها دمشقُ التي انطلقَ منها جيشُ البطلِ الذي تحملُ اسمَه! ونبيُّنا ﷺ دعا لها: اللهمَّ باركْ لنا في شامِنا.'],['صلاح الدين','(ينظر إلى أخته الرضيعة بعينين جديدتين) إذن نحن ثلاثة: نبيٌّ… وبطلٌ… وأرضٌ مباركة. (يفكر ثم يبتسم) عائلتُنا خريطةُ قصةٍ كاملة!']],vo:'نبيٌّ وبطلٌ وأرضٌ مباركة… لم يكن آباؤنا يسموننا عبثاً. كانوا يكتبون على أسمائنا عناوينَ الطريق.'}],
msg:'الدرس الذي تتعلمه حقاً هو الذي تعلّمه: من ذاق الغيرة وشُفي منها — صار أقدر الناس على شفاء غيره.',apply:'أنت راعٍ في بيتك مهما كان عمرك: اختر مهمة أسبوعية ثابتة تخدم بها إخوتك الأصغر (أو والديك إن كنت الأصغر).'},

{n:27,t:'حصّالةُ الدراجة',ic:'🚲',age:'٧ سنوات',loc:'البيت ومتجر الدراجات',corner:'social',goal:'الصبر والقناعة وإدارة المال: الادخار الحلال طريق الأمنيات',chars:['صلاح الدين','أيوب','مريم'],
scenes:[
{h:'م١ · خارجي — واجهة متجر الدراجات، بعد المدرسة',d:'أنف طفل ملتصق بزجاج الواجهة: دراجة حمراء لامعة بجرس فضي، تحتها بطاقة السعر. أيوب يقف خلفه صامتاً يقرأ وجه ابنه في انعكاس الزجاج.',dlg:[['صلاح الدين','بابا… هذه أجملُ دراجةٍ في مانشستر. في العالمِ كلِّه ربما. هل… تشتريها لي؟'],['أيوب','(يتأمل السعر بهدوء) أستطيعُ شراءَها لك اليوم… (عينا الطفل تلمعان)… لكني لن أفعل. (تنطفئان) لأن عندي لكَ ما هو أفضلُ من الدراجة.'],['صلاح الدين','(محبط) ماذا يكونُ أفضلَ من الدراجة؟!'],['أيوب','الطريقُ إليها. تعالَ وسترى.']],vo:'غضبتُ يومَها من أبي في سري: يستطيعُ ولا يفعل! ما هذا الأب؟… يا لجهلي. كان يعرضُ عليَّ كنزاً ولم أفهم.'},
{h:'م٢ · داخلي — البيت، عقد المشروع',d:'على طاولة المطبخ: حصالة زجاجية شفافة جديدة، وورقة يكتبها أيوب كعقد رسمي: «مشروع الدراجة الحمراء — الهدف: … المدة: ٣ أشهر — المصادر: ثلث المصروف + أعمال بأجر».',dlg:[['أيوب','هذا عقدُ رجل: ثلثُ مصروفِكَ يدخلُ الحصالةَ كلَّ أسبوع — وعندي أعمالٌ بأجرٍ لمن يريد: ترتيبُ الجراج جنيه، غسلُ السيارةِ جنيه ونصف، جمعُ أوراقِ الحديقةِ جنيه. الحصالةُ زجاجيةٌ عمداً — لترى مالَكَ يكبرُ كما يكبرُ الزرع.'],['صلاح الدين','(يوقع باسمه بخط متعرج ثم يبصق في كفه ويمدها) اتفاقُ رجال!'],['أيوب','(يضحك ويصافحه بدون بصق) اتفاقُ رجال — والنظافةُ من الإيمانِ يا شريكي.']]},
{h:'م٣ · خارجي/داخلي — مونتاج الكسب الحلال',d:'مونتاج ممتع بموسيقى إيقاعية: يغسل السيارة فيغرق نفسه بالرغوة — جنيه ونصف في الحصالة (طنين العملة صار نغمته المفضلة). يجمع أوراق الخريف في أكياس أطول منه. يرتب الجراج ويجد فيه مضربه المفقود. الحصالة الزجاجية تمتلئ ربعاً… ثم ثلثاً. يلصق عليها صورة الدراجة الحمراء قصها من إعلان.',vo:'اكتشفتُ شيئاً غريباً: الجنيهُ الذي أتعبُ فيه… ألمعُ في عيني من عشرةٍ تُعطى لي. كان لعرقِ اليدِ طعمٌ لم أعرفْهُ من قبل — طعمُ الكرامة.'},
{h:'م٤ · داخلي — متجر الألعاب، إغراء منتصف الطريق',d:'الشهر الثاني. مع أمه في السوق يمر بمتجر ألعاب: عرض ضخم على سيارة سباق تعمل بجهاز تحكم — «تخفيض! فقط ما يعادل نصف حصالتك!». يقف مسمراً. مريم تراقب ولا تتدخل. يمسك العلبة… يقلبها… ينظر لصورة الدراجة في محفظته الصغيرة.',dlg:[['صلاح الدين','(يعيد العلبة للرف ببطء مؤلم) لا… أنتِ لعبةُ أسبوع، وهي رفيقةُ سنين. (يلتفت لأمه) هيا بنا يا ماما… بسرعة قبل أن أغيرَ رأيي!'],['مريم','(تضحك وتسرع معه ممسكة يده) هذا يا حبيبي اسمُهُ عندنا: تأجيلُ اللذة — وهو سرُّ كلِّ العظماء. الذي يصبرُ على الأصغر… ينالُ الأكبر.']]},
{h:'م٥ · داخلي/خارجي — يوم الحصاد',d:'الحصالة تُفتح على الطاولة احتفالياً: عدّ جماعي للعملات في أعمدة. المبلغ يكتمل! في المتجر: يدفع بيده — البائع يعد النقود المعدنية مبتسماً — ويخرج بالدراجة الحمراء. لقطة أخيرة: ينطلق بها في الشارع والعائلة تصفق، وجرسها الفضي يرن.',dlg:[['البائع','(لأيوب) أول مرة أرى طفلاً يدفعُ ثمنَ دراجتِهِ بنفسِه… من أين له هذا؟'],['أيوب','(يضع يده على كتف ابنه) عملَ ثلاثةَ أشهرٍ وادّخر. هذه الدراجةُ لم تُشترَ… هذه بُنيت.']],vo:'ركبتُ في حياتي بعدَها سياراتٍ ودُعيتُ إلى قصور… لكن ما شعرتُ بنشوةِ ملكيةٍ كتلكَ الدراجةِ الحمراء. يا أصدقائي: الأمنياتُ لا تُشترى جاهزة… الأمنياتُ تُبنى قرشاً فوقَ قرش، وصبراً فوقَ صبر.'}],
msg:'الأمنيات تُبنى ولا تُشترى: ثلث المصروف والعمل الحلال وتأجيل اللذة — طريق الرجال إلى أحلامهم.',apply:'اختر أمنية واصنع حصالتها: اكتب الهدف والمبلغ عليها، وادّخر ثلث مصروفك حتى تبلغه — بلا استلاف.'},

{n:28,t:'حُمّى الليلةِ الطويلة',ic:'🤒',age:'٧ سنوات',loc:'غرفة صلاح الدين',corner:'heart',goal:'الصبر على المرض والرقية الشرعية — واسم «أيوب» يحكي قصته',chars:['صلاح الدين','أيوب','مريم'],
scenes:[
{h:'م١ · داخلي — غرفة صلاح الدين، ليل',d:'وجه طفل محموم على الوسادة، خدان متوردان وعينان زائغتان. مريم تبدل كمادة على جبينه. ميزان حرارة يظهر رقماً عالياً. في الخلفية: لوحة الصلوات ولوحة الجبل معلقتان — أسبوع كامل من الفراغات.',dlg:[['صلاح الدين','(بصوت مبحوح ودموع حارة) فاتني النادي… وفاتتني حلقةُ الحفظ… وسيسبقُني الجميعُ على الجبل! لماذا أنا يا ماما؟ ماذا فعلتُ حتى أمرض؟'],['مريم','(تجلس وتمسك يده الساخنة)… سؤالُكَ هذا يا حبيبي سألَهُ قبلَكَ الأنبياء. وسأحكي لكَ عن واحدٍ منهم… لكن انتظرْ صاحبَ الاسم.']],vo:'في السابعة، ظننتُ أن المرضَ عقوبة. وكنتُ على وشكِ أن أتعلمَ — من فمِ أبي الذي يحملُ الاسمَ نفسَه — أنه قد يكونُ وساماً.'},
{h:'م٢ · داخلي — الغرفة، حكاية النبي أيوب',d:'أيوب يدخل بكوب عصير دافئ، يجلس على الأرض بجانب السرير — عيناه بمستوى عيني ابنه المحموم.',dlg:[['أيوب','أتعرفُ على اسمِ من سماني جدُّكَ عبدُ القادر؟ نبيٌّ اسمُهُ أيوب… كان أغنى أهلِ زمانِهِ وأصحَّهم. ثم ابتلاهُ الله: ذهبَ المالُ، وذهبَ الأولاد، ومرضَ جسدُهُ كلُّهُ سنينَ طويلة… أتدري كم؟ ثمانيَ عشرةَ سنة!'],['صلاح الدين','(ينسى حماه من الهول) ثمانيَ عشرة؟! أنا لي ليلتان فقط! وماذا قال؟ هل غضب؟'],['أيوب','ما شكا لبشرٍ قط. وبعدَ كلِّ تلكَ السنين، رفعَ يديهِ وقال كلماتٍ رقيقةً أدَّبَ اللهُ بها الدعاء: ربِّ أني مسَّنيَ الضرُّ وأنتَ أرحمُ الراحمين. فماذا فعلَ اللهُ؟ شفاهُ في لحظة، وردَّ عليهِ مالَهُ وأهلَهُ ومثلَهم معهم! وسماهُ في القرآن: نِعمَ العبدُ، إنه أوّاب.'],['صلاح الدين','(يهمس مبهوراً)… نِعمَ العبد. ثمانيَ عشرةَ سنةً وما شكا… (ينظر لكمادته) أنا لن أشكوَ من كمادة!']]},
{h:'م٣ · داخلي — الغرفة، درس الرقية',d:'مريم تعلّمه العلاج النبوي عملياً: تضع يدها على جبينه.',dlg:[['مريم','والآن سلاحُ المريضِ المسلم — الرقية: نبيُّنا ﷺ كان يمسحُ على المريضِ ويقول: أذهبِ الباسَ ربَّ الناس، اشفِ وأنتَ الشافي، لا شفاءَ إلا شفاؤُك، شفاءً لا يغادرُ سقماً. قلها معي…'],['صلاح الدين','(يرددها ثلاثاً بصوته المبحوح، ويضع هو يده الصغيرة على جبين نفسه في الثالثة)'],['مريم','وبشارةٌ أخيرة تنامُ عليها: قال ﷺ ما يصيبُ المسلمَ من نصبٍ ولا وصبٍ ولا همٍّ ولا حزنٍ ولا أذىً ولا غم، حتى الشوكةِ يُشاكُها — إلا كفَّرَ اللهُ بها من خطاياه. حماكَ هذه الليلة… تحطُّ خطاياكَ كما تحطُّ الشجرةُ ورقَها في الخريف.'],['صلاح الدين','(يغمض عينيه مبتسماً لأول مرة منذ يومين) إذن أنا الليلةَ… شجرةُ خريف. تساقطي يا أوراق…']],vo:'ونمتُ تلكَ الليلةَ نومَ من فهمَ اللعبة: المرضُ ليس غضباً من السماء… أحياناً يكونُ غسيلاً للقلبِ ورفعاً للدرجات. وما زلتُ كلما مرضتُ أهمس: تساقطي يا أوراق.'},
{h:'م٤ · داخلي — الغرفة، مونتاج التعافي',d:'مونتاج قصير: الحمى تنكسر مع الفجر. حساء أمه. يوسف يدس له تحت الباب رسومات «اشفَ بسرعة». توم يترك عند الباب بطاقة وبرتقالة. اللون يعود لوجهه يوماً بعد يوم.',dlg:[['صلاح الدين','(يعد كنوزه على البطانية: رسومات يوسف وبطاقة توم) ماما… المرضُ كشفَ لي كم يحبُّني الناس! يكادُ يستحقُّ التجربة!'],['مريم','(تضحك) قم يا فيلسوف… اليومَ تعودُ للمدرسة.']]},
{h:'م٥ · خارجي/داخلي — العودة، وقلب التجربة عطاءً',d:'أول يوم بعد الشفاء: يمر بغرفة الممرضة في المدرسة فيعرف أن زميلاً (بيلي — الساخر القديم!) غائب مريض منذ أيام. بعد المدرسة: يقف صلاح الدين على باب بيت بيلي حاملاً عصيراً وبطاقة، وأمه خلفه.',dlg:[['بيلي','(يفتح الباب بوجه محموم، يذهل) أنت؟!… لماذا جئتَ أنت بالذات؟'],['صلاح الدين','لأني كنتُ مريضاً الأسبوعَ الماضي وعرفتُ كم هو ثقيل. اشرب — وقل معي: أذهبِ الباسَ ربَّ الناس… ستنفعُك، جرَّبتُها!'],['بيلي','(يأخذ العصير ببطء، شيء يذوب في وجهه)… شكراً. أنتَ… لستَ كما ظننتُك أبداً.']],vo:'عيادةُ المريضِ تفتحُ القلوبَ المغلقة — حتى قلوبَ الساخرين. تلكَ الزيارةُ القصيرة… كانت أولَ حجرٍ في جسرِ صداقةٍ لم أتوقعْها يوماً.'}],
msg:'المرض يحطّ الخطايا كما تحطّ الشجرة ورقها: اصبر كأيوب، وداوِ بالرقية، وحوّل تجربتك عيادةً لغيرك.',apply:'احفظ دعاء المريض: «أسأل الله العظيم رب العرش العظيم أن يشفيك» ٧ مرات — وعُد مريضاً هذا الأسبوع ولو باتصال.'},

{n:29,t:'جدّي خلفَ الشاشة',ic:'📱',age:'٧ سنوات ونصف',loc:'البيت — مكالمة إلى عمّان',corner:'parents',goal:'صلة الأرحام عبر المسافات — والجذور تنادي: حكايات الأرض والزيتون',chars:['العائلة','الجد عبد القادر','الجدة خديجة'],
scenes:[
{h:'م١ · داخلي — غرفة الجلوس، عصر الجمعة',d:'طقس أسبوعي مقدس واضح التنظيم: الأريكة الكبيرة تصطف عليها العائلة بترتيب ثابت، شاشة توضع على الطاولة، مريم تجهز الشاي «لنشرب معهم». صلاح الدين يمسك ورقة كتب فيها أسئلة الأسبوع لجده. الرنين… ثم يملأ الشاشةَ وجهان: الجد بكوفيته والجدة خديجة تزاحمه بصينية كعك ترفعها نحو الكاميرا.',dlg:[['الجدة خديجة','(تصيح بحنان) يا عيوني! يا حبايبَ قلبي! اقتربوا أراكم واحداً واحداً — يوسف كبر! والبنتُ الحلوةُ شام، قرّبوها!'],['الجد','(يدقق في صلاح الدين) وهذا الرجل… طالَ منذ الجمعةِ الماضية! أما زلتَ تصلي الفجرَ في المسجد؟'],['صلاح الدين','(بفخر) وأعدُّ خطواتي يا جدي! أربعُمئةٍ وسبعَ عشرة!']],vo:'جمعتُنا كانت لا تكتملُ إلا بهذه الشاشة. عجيبٌ أمرُ الأجداد… يسكنون على بُعدِ آلافِ الأميال، ويسكنون في قلبِكَ على بُعدِ دقّة.'},
{h:'م٢ · خارجي (عبر الشاشة) — حديقة بيت الجد، عمّان',d:'الجد يحمل الهاتف ويمشي به في حديقته: شمس عمّان الذهبية تغمر الصورة — تباين بصري صارخ مع رمادية مانشستر خلف العائلة. يصل إلى شجرة زيتون عتيقة ملتوية الجذع.',dlg:[['الجد','انظروا من أريكم… هذه الزيتونةُ غرسَها أبي — جدُّ جدِّكم — بيدِهِ قربَ القدس، ثم حملنا من نواها حينَ خرجنا، وغرسْتُ هذه من ذاكَ النوى. عمرُها من عمرِ حكايتِنا.'],['صلاح الدين','(يقترب من الشاشة حتى يكاد يدخلها) جدي… هل تثمرُ زيتوناً حقيقياً؟'],['الجد','وأطيبَ زيتٍ في عمّان! الزيتونةُ يا حبيبي لا تنسى أرضَها… تحملُ طعمَها معها أينما غُرست. (يقطف ورقة ويقربها من الكاميرا) مثلُنا تماماً.']]},
{h:'م٣ · داخلي (عبر الشاشة) — غرفة الجد، ظهور المفتاح',d:'الجد يجلس، يتردد لحظة، ثم يمد يده إلى صدره ويخرج من تحت ثوبه مفتاحاً حديدياً قديماً كبيراً معلقاً بخيط صوفي. صمت يعم الطرفين — حتى يوسف يتوقف عن الحركة.',dlg:[['صلاح الدين','(هامساً) ما… هذا المفتاح؟'],['الجد','هذا مفتاحُ بيتِنا في القدسِ القديمة. حملتُهُ وأنا في مثلِ عمرِكَ يومَ خرجنا… وقالت أمي: احفظْه، سنعودُ بعد أيام. (يبتسم ابتسامة موجعة) طالتِ الأيامُ يا صلاح الدين… لكنَّ المفتاحَ ما زالَ يعمل. البيوتُ تنتظرُ أصحابَها كما تنتظرُ الزيتونةُ أرضَها.'],['أيوب','(بصوت متحشرج) أبي… لم ترِنا إياهُ منذ سنين.'],['الجد','(ينظر مباشرة في عيني حفيده عبر الشاشة) اليومَ رأيتُ من يستحقُّ أن يعرفَ أنه موجود.']],vo:'أولُ مرةٍ أرى المفتاح. عبرَ شاشةٍ صغيرة، من على بُعدِ ثلاثةِ آلافِ ميل… ومع ذلك شعرتُ بثقلِهِ في صدري أنا. بعضُ الأماناتِ تُسلَّمُ بالنظرة… قبلَ أن تُسلَّمَ باليد.'},
{h:'م٤ · داخلي — ختام المكالمة، دعوات الجدة',d:'الجدة خديجة تزيح الجد عن الشاشة بلطف: وقت الدعوات — طقسها الثابت الذي تختم به كل مكالمة، ويردد الجميع آمين.',dlg:[['الجدة خديجة','(ترفع يديها) اللهُ يحفظُكم من كلِّ سوء… اللهُ يقرَّ عيونَنا بلمَّتِكم قريباً… اللهُ يجعلُ صغارَكم قرةَ عينٍ للإسلام… واللهُ يجمعُنا يا رب — لا في الشاشات — بل تحتَ سقفٍ واحد، على طبخةٍ من يدي!'],['الجميع','آمين!'],['يوسف','(يصيح) وعلى كعكِ الطابون يا تيتا!'],['الجدة','(تضحك وتقبّل الشاشة) وعلى كعكِ الطابون يا روحَ قلبي!']]},
{h:'م٥ · داخلي — بعد إغلاق الشاشة',d:'الشاشة تسودّ. البيت يعود فجأة لصمت مانشستر ومطرها على النافذة. صلاح الدين يبقى محدقاً في الشاشة السوداء، ثم يستدير لأبيه بالسؤال الذي كان يختمر طوال المكالمة.',dlg:[['صلاح الدين','بابا… جدي عندَهُ الشمسُ والزيتونةُ والمفتاح، وجدتي عندها الكعكُ والدعوات… لماذا نعيشُ نحن بعيداً عنهم؟'],['أيوب','(يتجمد — نظرة طويلة إلى مريم فوق رؤوس الأولاد… وصمت مثقل بالمستقبل)'],['مريم','(بهدوء، وهي تجمع أكواب الشاي) سؤالٌ كبيرٌ يا صلاح الدين… أحياناً تأتي الأجوبةُ الكبيرة… في أوانِها.']],vo:'لم يجبْني أبي تلكَ الليلة. لكني رأيتُ في عينيهِ أنَّ سؤالي وقعَ في مكانٍ عميق… كحجرٍ في بئر. وسمعتُ بعدَها، من خلفِ جدارِ غرفتي، حديثَهما الهامسَ يطولُ ويطول. شيءٌ ما… بدأ يتحرك.'}],
msg:'صلة الأرحام لا تعرف المسافات: اجعل للأجداد موعداً ثابتاً لا يسقط — فحكاياهم جذورك، ودعواتهم كنزك.',apply:'اجعل لأجدادك (أو أقاربك البعيدين) موعد اتصال أسبوعياً ثابتاً لا يسقط — واسألهم كل مرة عن حكاية من زمانهم.'},

{n:30,t:'حلمُ صلاحِ الدين',ic:'🌠',age:'٧ سنوات ونصف',loc:'غرفة صلاح الدين ومكتبة الأب',corner:'fortress',goal:'اللقاء الأول بالبطل التاريخي: من هو صلاح الدين الأيوبي؟ — الاسم يتحول إلى مشروع حياة',chars:['صلاح الدين','أيوب','مريم'],
scenes:[
{h:'م١ · داخلي — الحلم (تصوير حالم بألوان ذهبية ضبابية)',d:'طفل يمشي في أزقة حجرية قديمة مضاءة بنور غريب. يصل إلى أبواب ضخمة من خشب وذهب، مغلقة. يرفع يده: في كفه مفتاح جده الحديدي (الذي رآه أمس عبر الشاشة). صوت أذان بعيد يقترب… الأبواب تهتز… يمد المفتاح نحو القفل الكبير — ويستيقظ.',dlg:[['صلاح الدين','(يجلس في سريره لاهثاً، الفجر يتسلل من النافذة) الأبواب…! كان معي المفتاح…!']],vo:'رأيتُ الحلمَ في الليلةِ التي تلتْ ظهورَ المفتاحِ على الشاشة. قد يقولُ قائل: خيالُ طفلٍ تأثرَ بما رأى. ربما… لكنَّ اللهَ يصنعُ أحياناً من خيالاتِ الأطفالِ بوصلاتِ العمر.'},
{h:'م٢ · داخلي — مائدة الفطور',d:'يحكي الحلم بتفاصيله والعائلة تنصت. ملعقة أيوب تتوقف في منتصف الطريق. يتبادل الوالدان تلك النظرة المعهودة — لكن هذه المرة يحسمها أيوب بوضع الملعقة وقيامه عن الطاولة.',dlg:[['أيوب','تعال معي يا صلاح الدين… أظنُّ أن الوقتَ حان.'],['صلاح الدين','حانَ لماذا؟'],['أيوب','لتعرفَ أخيراً… من هوَ الرجلُ الذي تحملُ اسمَه.']]},
{h:'م٣ · داخلي — المكتبة، الحكاية الكبرى (الجزء الأول)',d:'أيوب يخرج من الرف الأعلى كتاباً مصوراً كان ينتظر: «الناصر صلاح الدين». يجلسان على الأرض. مع الحكي تظهر رسوم الكتاب بتحريك بسيط: خرائط ممزقة، قلاع متناحرة.',dlg:[['أيوب','قبل مئاتِ السنين، كانت أمتُنا كما لا تتخيل: ممزقةً إماراتٍ صغيرةً يقاتلُ بعضُها بعضاً… والقدسُ — قدسُنا التي على الجدار — مأسورةً بيدِ غزاةٍ جاؤوا من وراءِ البحار. وذاتَ يومٍ وُلدَ طفلٌ اسمُهُ يوسفُ بنُ أيوب…'],['صلاح الدين','(مقاطعاً بذهول) يوسف؟ ابنُ أيوب؟! مثلُ أخي… وأنت؟!'],['أيوب','(يبتسم) لاحظتَ أخيراً لماذا اخترنا الأسماء؟… كبُرَ يوسفُ هذا وتعلمَ القرآنَ والفروسيةَ والعلم، ولُقِّبَ: صلاحَ الدين. وفهمَ وهو شابٌّ سرّاً غابَ عن الجميع: القدسُ لن تعودَ وأهلُها متفرقون. فماذا يفعلُ برأيك؟'],['صلاح الدين','يجمعُهم!'],['أيوب','قضى عمرَهُ كلَّهُ يجمعُهم! مدينةً مدينة، وقلباً قلباً… يصالحُ هذا، ويصبرُ على ذاك، ويعفو عن ذاك — ثلاثين سنةً من توحيدِ القلوبِ قبل أن يرفعَ السيف.']]},
{h:'م٤ · داخلي — المكتبة، الحكاية الكبرى (حطين والفتح والرحمة)',d:'الرسوم تتصاعد: حطين، ثم أسوار القدس، ثم المشهد الذي يركز عليه الأب.',dlg:[['أيوب','وفي يومٍ مشهودٍ عند قرونِ حطين، نصرَهُ الله… وفُتحتِ القدس. والآن أهمُّ جزءٍ في القصةِ كلِّها — أتدري ماذا فعلَ بأهلِها المهزومين الذين كانوا قد ذبحوا المسلمين يومَ دخلوها؟'],['صلاح الدين','(بحماس طفولي) انتقمَ منهم؟!'],['أيوب','عفا. أمَّنَهم على أرواحِهم، وحرسَ كنائسَهم، وأطلقَ أسراهم، وبكى الفقراءُ منهم فأعطاهم من مالِه. حتى أعداؤهُ كتبوا في تاريخِهم: ما رأينا أنبلَ منه. هذه يا صلاح الدين قوةُ المسلمِ الحقيقية — يملكُ أن ينتقمَ… فيرحم.'],['صلاح الدين','(صمت طويل… ثم بصوت صغير) بابا… ولماذا سمَّيتموني باسمِهِ أنا؟'],['أيوب','(يمسك كتفيه وينظر في عينيه) لأن القدسَ يا بني… ما زالت تنتظر. ولأن جدَّكَ قال يومَ ولدت: سمِّهِ صلاحَ الدين وربِّهِ على قَدْرِ اسمِه. الاسمُ ليس ذكرى نعلقُها عليك… الاسمُ مشروعٌ نسلمُهُ إليك.']],vo:'في تلكَ الجلسةِ على سجادةِ المكتبة… وُلدتُ مرةً ثانية. دخلتُها طفلاً يحملُ اسماً، وخرجتُ منها طفلاً يحملُ أمانة.'},
{h:'م٥ · داخلي — غرفة صلاح الدين، ليلاً',d:'الطفل واقف على كرسيه أمام الجدار: تحت رسمة القبة الذهبية القديمة (من حلقة الطفولة) يلصق ورقة جديدة كتبها بأجمل خطه، ويقرؤها بصوت عالٍ كقسم. مريم وأيوب يراقبان من شق الباب.',dlg:[['صلاح الدين','(يقرأ ما كتب) «صلاحُ الدينِ الأولُ وحَّدَ وحرَّرَ ورحِم. وأنا صلاحُ الدينِ الثاني… سأكونُ على قَدْرِ اسمي». (يفكر ثم يضيف بالقلم سطراً) «وسأبدأ غداً: سأصالحُ بيلي في المدرسة».'],['مريم','(هامسة لأيوب ودمعتها تنزل) سيصالحُ بيلي… يبدأُ بتوحيدِ القلوب. فهمَ القصةَ يا أيوب… فهمَها أعمقَ مما حكيتَها.']],vo:'وهكذا اكتملتِ البذرةُ الأولى: حلمٌ… ومفتاحٌ… وحكايةُ بطلٍ… وقرارُ طفلٍ في السابعةِ أن يصالحَ زميلَهُ غداً. تضحكون؟ لا تضحكوا… فكلُّ الفتوحاتِ العظيمةِ في التاريخ، بدأتْ يوماً بقرارٍ بحجمِ: سأصالحُ بيلي.'}],
msg:'الاسمُ مشروعٌ لا ذكرى: صلاح الدين وحّد القلوب ثلاثين سنة قبل أن يحرر — وأعظم الفتوحات تبدأ بقرار صغير.',apply:'ابحث عن معنى اسمك وعن عظيمٍ من عظماء المسلمين حمله (أو حمل مثله) — واكتب: «سأكون على قدر اسمي لأن…».'}
]});
